SOLTANI_PLACEMENT_EXAMPLES = {
    ('مشتری', 2): 'نمونه: سروری مشتری در حوت قرینهٔ تقویت دلالت مالی این جایگاه است.',
    ('زحل', 2): 'نمونه: نظر مساعد مشتری به زحل می‌تواند تعبیر محدودیت مالی را تعدیل کند.',
    ('عطارد', 9): 'نمونه: شرف عطارد و حضورش در این خانه دو قرینهٔ جدا برای موضوع دانش‌اند.',
}


def soltani_house_note(planet_name: str, house: int) -> str:
    _, topics, _ = SOLTANI_HOUSES[house]
    entry = SOLTANI_PLANETS.get(planet_name)
    if not entry:
        return f'موضوع این خانه {topics} است.'
    role, _, placements = entry
    state = next((label for label, number in zip(SOLTANI_HOUSE_STATES, placements) if number == house), '')
    parts = [f'{role} را در زمینهٔ «{topics}» بررسی کنید.']
    if state:
        parts.append(f'این خانه {state} این کوکب است.')
    example = SOLTANI_PLACEMENT_EXAMPLES.get((planet_name, house))
    if example:
        parts.append(example)
    return ' '.join(parts)
